      .actions {
        align-items: stretch;
      }

      button {
        width: 100%;
      }
    }
  </style>
</head>
<body>
  <main class="quiz-shell">
    <header class="quiz-header">
      <div class="eyebrow">Interactive quiz</div>
      <h1>Computer Languages Knowledge Check</h1>
      <p>Select every answer you believe is correct for each question, then submit to review your picks.</p>
    </header>

    <form id="quiz-form">
      <div class="form-field">
        <div class="question-meta">
          <div class="question-number">1</div>
          <h2 class="question-title">Which of these are programming languages?</h2>
        </div>
        <p class="help-text">Tip: More than one answer is correct, so choose every option that fits.</p>
        <div class="choices">
          <label class="choice"><input type="checkbox" name="q1" value="Python"><span>Python</span></label>
