          <label class="choice"><input type="checkbox" name="q1" value="Java"><span>Java</span></label>
          <label class="choice"><input type="checkbox" name="q1" value="CSS"><span>CSS</span></label>
        </div>
      </div>

      <div class="form-field">
        <div class="question-meta">
          <div class="question-number">2</div>
          <h2 class="question-title">Which languages are commonly used for styling or structuring web pages?</h2>
