          <label class="choice"><input type="checkbox" name="q2" value="CSS"><span>CSS</span></label>
          <label class="choice"><input type="checkbox" name="q2" value="HTML"><span>HTML</span></label>
          <label class="choice"><input type="checkbox" name="q2" value="Rust"><span>Rust</span></label>
          <label class="choice"><input type="checkbox" name="q2" value="SQL"><span>SQL</span></label>
        </div>
      </div>

      <div class="form-field">
        <div class="question-meta">
          <div class="question-number">3</div>
          <h2 class="question-title">Which languages are often used for systems or backend development?</h2>
        </div>
        <div class="choices">
          <label class="choice"><input type="checkbox" name="q3" value="C++"><span>C++</span></label>
          <label class="choice"><input type="checkbox" name="q3" value="Go"><span>Go</span></label>
          <label class="choice"><input type="checkbox" name="q3" value="Ruby"><span>Ruby</span></label>
          <label class="choice"><input type="checkbox" name="q3" value="Photoshop"><span>Photoshop</span></label>
        </div>
      </div>

      <div class="actions">
        <button type="submit">Submit quiz</button>
        <div id="result" aria-live="polite"></div>
      </div>
    </form>
  </main>

  <script>
    const form = document.getElementById("quiz-form");
    const result = document.getElementById("result");
    const questionNames = ["q1", "q2", "q3"];

    form.addEventListener("submit", (event) => {
      event.preventDefault();

      const summary = questionNames.map((name, index) => {
        const selected = Array.from(form.querySelectorAll(`input[name="${name}"]:checked`))
          .map((input) => input.value);
        return `Q${index + 1}: ${selected.length ? selected.join(", ") : "No answers selected"}`;
      });

      result.textContent = `Selections saved. ${summary.join(" | ")}`;
      result.className = "success";
    });
  </script>
</body>
</html>
